import * as React from "react";
import { Box, Typography } from "@mui/material";

export default function MakeupPage() {
  const days = ["MON", "TUE", "WED", "THU", "FRI"];

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        backgroundImage: "url('/Background15.jpg')",
        backgroundSize: "cover",
        backgroundPosition: "center",
        padding: { xs: 2, sm: 4 },
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
      }}
    >
      <Typography
        variant="h3"
        sx={{
          fontFamily: "'Playfair Display', serif",
          fontWeight: 700,
          textAlign: "center",
          marginBottom: { xs: 2, sm: 3 },
          fontSize: { xs: "1.8rem", sm: "2.5rem" },
          color: "#6B4F4F",
        }}
      >
        Available Makeup Appointments
      </Typography>
      <Typography
        variant="subtitle1"
        sx={{
          fontFamily: "'Playfair Display', serif",
          textAlign: "center",
          marginBottom: { xs: 3, sm: 4 },
          fontSize: { xs: "1rem", sm: "1.2rem" },
          color: "#6B4F4F",
        }}
      >
        Book Now
      </Typography>
      {days.map((day, index) => (
        <Box
          key={index}
          sx={{
            width: "100px", // Same width as HairPage
            height: "50px",
            backgroundColor: "#BBAFA2",
            color: "white",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            borderRadius: 4,
            fontWeight: "bold",
            textAlign: "center",
            marginBottom: 2,
            cursor: "pointer",
            boxShadow: "0 2px 4px rgba(0, 0, 0, 0.2)", // Same button effect
            transition: "0.3s",
            "&:hover": {
              backgroundColor: "#A89C8C",
            },
          }}
        >
          <Typography
            variant="h6"
            sx={{
              fontFamily: "'Roboto', sans-serif",
              fontWeight: 700,
              fontSize: { xs: "1rem", sm: "1.2rem" },
            }}
          >
            {day}
          </Typography>
        </Box>
      ))}
    </Box>
  );
}
